package compat

import (
	"encoding/json"
	"fmt"
	"reflect"
	"strings"
	"testing"
)

// These fixtures are independently authored from the committed compatibility
// contracts, not generated by decoding an example and recording its output.
// Each expected fragment is an explicit assertion about a field, alias, default,
// integer boundary, union discriminator, or unknown-field preservation rule.
// They establish compatibility behavior, not independent historical evidence.
func TestCompatibilityGoldens(t *testing.T) {
	factories := map[string]func() any{
		"inventory": func() any { return &UserInventory{} }, "item": func() any { return &UserInventoryItem{} },
		"company": func() any { return &CompanyProfile{} }, "profile": func() any { return &CompanyProfileBundle{} },
		"news": func() any { return &CompanyNewsBundle{} }, "employee": func() any { return &CompanyEmployee{} },
		"upgrades":   func() any { return &CompanyUpgrades{} },
		"employment": func() any { return &UserEmployment{} }, "competition": func() any { return &UserCompetition{} },
		"warfare": func() any { return &FactionWarfareEntry{} }, "crime": func() any { return &UserOrganizedCrimeSelection{} },
		"trade": func() any { return &TradeItem{} }, "dynamic": func() any { return &DynamicValue{} },
		"metadata": func() any { return &PaginatedMetadata{} }, "stats": func() any { return &UserPersonalStatsBucket{} },
		"details": func() any { return &UserReportDetails{} }, "application": func() any { return &CompanyApplicationSummary{} },
		"userprofile": func() any { return &UserProfile{} }, "personal": func() any { return &UserPersonalStatsSelection{} },
	}
	cases := []struct {
		name, model, input, want, variant string
		reject                            bool
	}{
		{"inventory defaults", "inventory", `{}`, `"items":[]`, "", false},
		{"inventory timestamp missing", "inventory", `{}`, `"timestamp":null`, "", false},
		{"inventory extras", "inventory", `{"future":{"x":3}}`, `"future":{"x":3}`, "", false},
		{"inventory explicit null array", "inventory", `{"items":null}`, "", "", true},
		{"inventory wrong array", "inventory", `{"items":{}}`, "", "", true},
		{"inventory not object", "inventory", `[]`, "", "", true},
		{"inventory null object", "inventory", `null`, "", "", true},
		{"inventory child exact integer", "inventory", `{"items":[{"id":9007199254740993}]}`, `"id":9007199254740993`, "", false},
		{"inventory child negative id", "inventory", `{"items":[{"id":-1}]}`, "", "", true},
		{"item uint64 maximum", "item", `{"id":18446744073709551615}`, `"id":18446744073709551615`, "", false},
		{"item uint64 overflow", "item", `{"id":18446744073709551616}`, "", "", true},
		{"item fractional id", "item", `{"id":1.1}`, "", "", true},
		{"item string id", "item", `{"id":"1"}`, "", "", true},
		{"item false preserved", "item", `{"equipped":false}`, `"equipped":false`, "", false},
		{"item null preserved", "item", `{"equipped":null}`, `"equipped":null`, "", false},
		{"company uppercase alias", "company", `{"ID":7}`, `"id":7`, "", false},
		{"company duplicate aliases", "company", `{"id":7,"ID":7}`, "", "", true},
		{"company known null", "company", `{"name":null}`, `"name":null`, "", false},
		{"company signed lower boundary", "company", `{"funds":-9223372036854775808}`, `"funds":-9223372036854775808`, "", false},
		{"company signed overflow", "company", `{"funds":9223372036854775808}`, "", "", true},
		{"company wrong name type", "company", `{"name":4}`, "", "", true},
		{"company preserves nested unknown", "company", `{"new":{"counter":9007199254740993}}`, `"new":{"counter":9007199254740993}`, "", false},
		{"profile default company", "profile", `{}`, `"company":{`, "", false},
		{"profile renamed alias", "profile", `{"profile":{"ID":42}}`, `"id":42`, "", false},
		{"profile duplicate aliases", "profile", `{"company":{},"profile":{}}`, "", "", true},
		{"profile null company", "profile", `{"company":null}`, "", "", true},
		{"news default map", "news", `{}`, `"news":{}`, "", false},
		{"news null map", "news", `{"news":null}`, `"news":{}`, "", false},
		{"news object map", "news", `{"news":{"n":{"news":"hello"}}}`, `"news":"hello"`, "", false},
		{"news array id key", "news", `{"news":[{"id":"a","news":"hello"}]}`, `"news":{"a":`, "", false},
		{"news array timestamp key", "news", `{"news":[{"timestamp":1700000000}]}`, `"news":{"1700000000":`, "", false},
		{"news array index key", "news", `{"news":[{}]}`, `"news":{"0":`, "", false},
		{"news wrong scalar", "news", `{"news":"invalid"}`, "", "", true},
		{"position object coercion", "employee", `{"position":{"name":"Director","id":1}}`, `"position":"Director"`, "", false},
		{"position string coercion", "employee", `{"position":"Employee"}`, `"position":"Employee"`, "", false},
		{"position unsupported coercion", "employee", `{"position":false}`, `"position":null`, "", false},
		{"stringish exact number", "upgrades", `{"storage_capacity":9007199254740993}`, `"storage_capacity":"9007199254740993"`, "", false},
		{"stringish string", "upgrades", `{"storage_capacity":"1000"}`, `"storage_capacity":"1000"`, "", false},
		{"stringish boolean", "upgrades", `{"storage_capacity":false}`, `"storage_capacity":null`, "", false},
		{"stringish object", "upgrades", `{"storage_capacity":{}}`, `"storage_capacity":null`, "", false},
		{"employment city discriminator", "employment", `{"type":"job","name":"Army"}`, `"name":"Army"`, "UserCityJob", false},
		{"employment company discriminator", "employment", `{"type":"company","id":1}`, `"id":1`, "UserCompanyJob", false},
		{"employment unknown discriminator", "employment", `{"type":"future","x":1}`, `"job_type":"future"`, "UnknownUserEmployment", false},
		{"employment scalar preservation", "employment", `12`, `"raw":12`, "UnknownUserEmployment", false},
		{"competition halloween discriminator", "competition", `{"name":"Halloween"}`, `"name":"Halloween"`, "UserHalloweenCompetition", false},
		{"competition easter discriminator", "competition", `{"name":"Easter Egg Hunt"}`, `"name":"Easter Egg Hunt"`, "UserEasterCompetition", false},
		{"competition rps discriminator", "competition", `{"name":"Rock, Paper, Scissors"}`, `"name":"Rock, Paper, Scissors"`, "UserRpsCompetition", false},
		{"competition elimination discriminator", "competition", `{"name":"Elimination"}`, `"name":"Elimination"`, "UserEliminationCompetition", false},
		{"competition unknown discriminator", "competition", `{"name":"Future","new":true}`, `"new":true`, "UnknownUserCompetition", false},
		{"warfare unknown preservation", "warfare", `{"future":4}`, `"future":4`, "FactionUnknownWarfareEntry", false},
		{"crime error discriminator", "crime", `{"code":6,"error":"missing"}`, `"code":6`, "UserOrganizedCrimeError", false},
		{"crime null selection", "crime", `null`, `null`, "UserOrganizedCrime", false},
		{"trade money discriminator", "trade", `{"type":"Money","user_id":1,"details":{"amount":23}}`, `"amount":23`, "TradeMoneyItem", false},
		{"trade future discriminator", "trade", `{"type":"Future","details":{"x":2},"more":true}`, `"item_type":"Future"`, "UnknownTradeItem", false},
		{"trade nonobject rejected", "trade", `[]`, "", "", true},
		{"dynamic null", "dynamic", `null`, `null`, "Null", false},
		{"dynamic boolean", "dynamic", `false`, `false`, "Bool", false},
		{"dynamic integer", "dynamic", `9007199254740993`, `9007199254740993`, "Int64", false},
		{"dynamic unsigned maximum", "dynamic", `18446744073709551615`, `18446744073709551615`, "Number", false},
		{"dynamic decimal precision", "dynamic", `1.234567890123456789`, `1.234567890123456789`, "Number", false},
		{"dynamic numeric string", "dynamic", `"123"`, `"123"`, "String", false},
		{"dynamic string", "dynamic", `"hello"`, `"hello"`, "String", false},
		{"dynamic array", "dynamic", `[1,"a",false]`, `[1,"a",false]`, "Array", false},
		{"dynamic object", "dynamic", `{"a":9007199254740993}`, `"a":9007199254740993`, "Object", false},
		{"metadata unknown preservation", "metadata", `{"page":3}`, `"page":3`, "", false},
		{"metadata nullable links", "metadata", `{"links":null}`, `"links":null`, "", false},
		{"metadata nested links", "metadata", `{"links":{"next":"next-page"}}`, `"next":"next-page"`, "", false},
		{"stats flattened numeric map", "stats", `{"attacks":9007199254740993}`, `"attacks":9007199254740993`, "", false},
		{"details flattened object map", "details", `{"field":{"x":2}}`, `"field":{"x":2}`, "", false},
		{"application expiration alias", "application", `{"expires_at":10}`, `"valid_until":10`, "", false},
		{"application alias collision", "application", `{"expires_at":10,"valid_until":10}`, "", "", true},
		{"user profile unsigned32 max", "userprofile", `{"level":4294967295}`, `"level":4294967295`, "", false},
		{"user profile unsigned32 overflow", "userprofile", `{"level":4294967296}`, "", "", true},
		{"personal stats list variant", "personal", `[]`, `[]`, "Array", false},
		{"personal stats raw unknown variant", "personal", `"future"`, `"future"`, "Raw", false},
	}
	if len(cases) < 59 {
		t.Fatal("compatibility golden inventory incomplete")
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			value := factories[tc.model]()
			e := json.Unmarshal([]byte(tc.input), value)
			if tc.reject {
				if e == nil {
					t.Fatal("invalid documented boundary accepted")
				}
				return
			}
			if e != nil {
				t.Fatal(e)
			}
			raw, e := json.Marshal(value)
			if e != nil {
				t.Fatal(e)
			}
			if !strings.Contains(string(raw), tc.want) {
				t.Fatalf("want fragment %s; got %s", tc.want, raw)
			}
			if tc.variant != "" {
				v := reflect.ValueOf(value).Elem().FieldByName(tc.variant)
				if !v.IsValid() || v.IsNil() {
					t.Fatalf("expected typed union variant %s; got %+v", tc.variant, value)
				}
			}
		})
	}
}
func TestCompatibilityPublicAccessors(t *testing.T) {
	var p CompanyProfileBundle
	if e := json.Unmarshal([]byte(`{"company":{"id":3}}`), &p); e != nil {
		t.Fatal(e)
	}
	if p.Profile().ID == nil || *p.Profile().ID != 3 {
		t.Fatal("profile accessor")
	}
	var s UserPersonalStatsBucket
	if e := json.Unmarshal([]byte(`{"attacks":9007199254740993}`), &s); e != nil {
		t.Fatal(e)
	}
	n, ok := s.Get("attacks")
	if !ok || n.Int64 == nil || *n.Int64 != 9007199254740993 {
		t.Fatal("exact stats accessor")
	}
	if _, ok = s.Get("missing"); ok {
		t.Fatal("missing stats value")
	}
	var d UserReportDetails
	if e := json.Unmarshal([]byte(`{"confirmed":true}`), &d); e != nil {
		t.Fatal(e)
	}
	if v, ok := d.Get("confirmed"); !ok || v.Bool == nil || !*v.Bool {
		t.Fatal("report details accessor")
	}
}
func FuzzCompatibilityInventory(f *testing.F) {
	for _, v := range []string{`{}`, `{"items":[{"id":18446744073709551615}]}`, `null`} {
		f.Add(v)
	}
	f.Fuzz(func(t *testing.T, s string) {
		var v UserInventory
		if json.Unmarshal([]byte(s), &v) == nil {
			b, e := json.Marshal(v)
			if e != nil || !json.Valid(b) {
				t.Fatal(fmt.Sprint(e))
			}
		}
	})
}
